void drawRotarySlider (juce::Graphics& g, int x, int y, int width, int height, 
                      float sliderPos, const float rotaryStartAngle, 
                      const float rotaryEndAngle, juce::Slider& slider) override
{
    auto radius = (float) juce::jmin (width / 2, height / 2) - 4.0f;
    auto centreX = (float) x + (float) width * 0.5f;
    auto centreY = (float) y + (float) height * 0.5f;
    auto rx = centreX - radius;
    auto ry = centreY - radius;
    auto rw = radius * 2.0f;
    auto angle = rotaryStartAngle + sliderPos * (rotaryEndAngle - rotaryStartAngle);

    // Background arc
    g.setColour (slider.findColour (juce::Slider::rotarySliderFillColourId).withAlpha (0.3f));
    {
        juce::Path backgroundArc;
        backgroundArc.addPieSegment (rx, ry, rw, rw, rotaryStartAngle, rotaryEndAngle, 0.0);
        g.fillPath (backgroundArc);
    }

    // Value arc
    g.setColour (slider.findColour (juce::Slider::rotarySliderFillColourId));
    {
        juce::Path valueArc;
        valueArc.addPieSegment (rx, ry, rw, rw, rotaryStartAngle, angle, 0.0);
        g.fillPath (valueArc);
    }

    // Outline
    auto lineThickness = juce::jmin (15.0f, (float) juce::jmin (width, height) * 0.45f) * 0.1f;
    g.setColour (slider.findColour (juce::Slider::rotarySliderOutlineColourId));
    g.strokePath (outlineArc, juce::PathStrokeType (lineThickness));

    // Thumb/pointer
    juce::Path p;
    auto pointerLength = radius * 0.33f;
    auto pointerThickness = 2.0f;
    p.addRectangle (-pointerThickness * 0.5f, -radius, pointerThickness, pointerLength);
    p.applyTransform (juce::AffineTransform::rotation (angle).translated (centreX, centreY));

    g.setColour (juce::Colours::white);
    g.fillPath (p);
}

