void setupCustomLookAndFeelColours()
{
    // Sliders
    setColour (juce::Slider::thumbColourId,               juce::Colour (0xff00b5f6));
    setColour (juce::Slider::rotarySliderFillColourId,    juce::Colour (0xff00b5f6));
    setColour (juce::Slider::rotarySliderOutlineColourId, juce::Colours::white);
    setColour (juce::Slider::trackColourId,               juce::Colours::darkgrey);
    setColour (juce::Slider::textBoxOutlineColourId,      juce::Colours::transparentWhite);

    // Buttons
    setColour (juce::TextButton::buttonColourId,  juce::Colours::white);
    setColour (juce::TextButton::textColourOffId, juce::Colour (0xff00b5f6));
    setColour (juce::TextButton::buttonOnColourId, juce::Colours::lightblue);

    // Labels
    setColour (juce::Label::textColourId, juce::Colours::white);
    setColour (juce::Label::backgroundColourId, juce::Colours::transparentBlack);

    // ComboBox
    setColour (juce::ComboBox::backgroundColourId, juce::Colours::darkgrey);
    setColour (juce::ComboBox::textColourId, juce::Colours::white);

    // PopupMenu
    setColour (juce::PopupMenu::backgroundColourId, juce::Colours::darkgrey);
    setColour (juce::PopupMenu::textColourId, juce::Colours::white);
    setColour (juce::PopupMenu::highlightedBackgroundColourId, juce::Colour (0xff00b5f6));
    setColour (juce::PopupMenu::highlightedTextColourId, juce::Colours::white);
}

