// PluginEditor.cpp
MyPluginEditor::MyPluginEditor (MyPluginProcessor& p)
    : AudioProcessorEditor (&p), processor (p)
{
    setSize (400, 300);

    // Setup and apply look and feel
    addAndMakeVisible (gainKnob);
    gainKnob.setSliderStyle (juce::Slider::RotaryHorizontalVerticalDrag);
    gainKnob.setLookAndFeel (&customLNF);
    gainKnob.setRange (-48.0, 12.0, 0.1);
    gainKnob.setTextValueSuffix (" dB");

    // Setup other components...

    // Start timer for meters if needed
    startTimerHz (30);
}

MyPluginEditor::~MyPluginEditor()
{
    setLookAndFeel (nullptr); // Important cleanup
    gainKnob.setLookAndFeel (nullptr);
    // ... cleanup other components
}

void MyPluginEditor::paint (juce::Graphics& g)
{
    g.fillAll (getLookAndFeel().findColour (juce::ResizableWindow::backgroundColourId));
}

void MyPluginEditor::resized()
{
    gainKnob.setBounds (20, 20, 100, 100);
    // ... layout other components
}

