void setTheme (Theme newTheme)
{
    if (newTheme == Theme::dark)
        setLookAndFeel (&darkLookAndFeel);
    else
        setLookAndFeel (&lightLookAndFeel);

    // Update all child components
    for (auto* child : getChildren())
        child->repaint();
}
